function validateIntro(){if(!INTRO.every((s,i)=>s.id&&s.scene&&Array.isArray(s.actors)&&Array.isArray(s.objects)&&(!i||INTRO[i-1].id!==s.id)))audit.push("intro timeline");if(!["expected","own","different","letter"].every(k=>endingSequences[k]?.at(-1)?.ending))audit.push("ending route");if(!chapters.every(k=>story[k]?.length))audit.push("story entry");if(!Object.entries(options).every(([k,v])=>v.every(value=>document.querySelector(`[data-field="${k}"][data-value="${value}"]`))))audit.push("customization");}
