 shot.objects.forEach(([name,x,y,size,motion])=>filmObject(name,x,y,size,motion));
 $("film-year").textContent=shot.year||"";$("film-caption-text").textContent=shot.caption||"";$("film-caption").classList.toggle("hidden",!shot.year&&!shot.caption);
