 if(shot.phone){const log=$("chat");log.replaceChildren();const bubble=document.createElement("div");bubble.className="bubble";const label=document.createElement("small");label.textContent="UNKNOWN NUMBER";const text=document.createElement("span");text.textContent="Are you there?";bubble.append(label,text);log.append(bubble)}
