function renderVisual(b){$("art").innerHTML=sceneArt(b.scene);$("weather").className="weather"+(b.effect&&!reduced()?" "+b.effect:"");$("actors").replaceChildren();(b.cast||[]).forEach((name,i,all)=>{const e=document.createElement("div");e.className="actor"+(name.toLowerCase()===b.speaker.toLowerCase()?" active":"");e.style.setProperty("--actor-x",all.length===1?"40%":all.length===2?(i?"72%":"30%"):(i===0?"23%":i===1?"52%":"80%"));e.setAttribute("role","img");e.setAttribute("aria-label",name==="mira"?safeName(state.miraPresentation.displayName):name);e.innerHTML=portrait(name);$("actors").append(e)});$("props").replaceChildren();if(propArt[b.prop]){const p=document.createElement("div");p.className="prop";p.setAttribute("role","img");p.setAttribute("aria-label",b.prop);p.innerHTML=`<svg xmlns="${NS}" viewBox="0 0 100 100" aria-hidden="true">${propArt[b.prop]}</svg>`;$("props").append(p)}const label=[year(b.scene),locations[b.scene]?.split(" · ")[0],b.kind].filter(Boolean).join(" · ").toUpperCase();$("scene-label").textContent=label;$("scene-label").classList.toggle("hidden",!label);$("stage").setAttribute("aria-label","Illustration of "+(locations[b.scene]||"the story"));}
function marker(scene){const y=year(scene);if(!y||y===lastTimeline)return;lastTimeline=y;const card=document.createElement("div");card.className="time-card";card.textContent=y==="2024"?"2024 · MIRA, 22":"2048 · ELARA, 17";$("stage").append(card);later(()=>card.remove(),1800)}
function musicStart(){if(audio){audio.resume?.().then(()=>setMood()).catch(()=>{});return}try{const A=window.AudioContext||window.webkitAudioContext;if(!A)return;audio=new A();musicGain=audio.createGain();musicGain.gain.value=0;musicGain.connect(audio.destination);audio.resume().then(()=>setMood()).catch(()=>{})}catch(_){}}
function sound(f){return;if(!audio||audio.state!=="running"||!state.settings.effects)return;const t=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();o.frequency.value=f;g.gain.setValueAtTime(.0001,t);g.gain.linearRampToValueAtTime(state.settings.effects/6000,t+.03);g.gain.exponentialRampToValueAtTime(.0001,t+.19);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+.21)}
function silentMood(){if(musicGain&&audio)musicGain.gain.setTargetAtTime(0,audio.currentTime,.06);musicMood="silent"}
function setMood(override){if(!audio||audio.state!=="running")return;const b=beat(),m=override||((introPhase==="film"||introPhase==="customization")?"intro":state.chapter==="title"?"opening":b?.scene==="archive"?"archive":b?.scene==="wedding"?"wedding":b?.scene==="future"?"bedroom":state.chapter==="ending"?"hopeful":"warm");if(m!==musicMood){musicNodes.forEach(({o,g})=>{g.gain.setTargetAtTime(0,audio.currentTime,.1);try{o.stop(audio.currentTime+.5)}catch(_){}});musicNodes=[];musicMood=m;const chords={intro:[174.61,220,261.63],opening:[220,261.63,329.63],bedroom:[196,246.94,329.63],warm:[220,277.18,329.63],archive:[174.61,261.63,349.23],wedding:[196,246.94,329.63],hopeful:[220,277.18,369.99],projector:[110,146.83,174.61],city:[174.61,220,261.63],box:[196,246.94,329.63],paper:[196,246.94,329.63],notification:[196,246.94,329.63],fabric:[220,277.18,329.63],romance:[220,277.18,329.63],steps:[220,277.18,329.63],unease:[174.61,207.65,261.63],swell:[196,246.94,329.63],heartbeat:[110,164.81,220]};(chords[m]||chords.warm).forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.type=i?"triangle":"sine";o.frequency.value=i?f:f/2;g.gain.value=0;g.gain.setTargetAtTime(0,audio.currentTime,.8);o.connect(g);g.connect(musicGain);o.start();musicNodes.push({o,g})})}musicGain.gain.setTargetAtTime(state.settings.musicOn?state.settings.music/6000:0,audio.currentTime,.2)}
function history(eventId,speaker,text){if(!state.history.some(h=>h.id===eventId))state.history.push({id:eventId,speaker,text});state.history=state.history.slice(-85)}
function button(text,fn,primary=false,final=false){const el=document.createElement("button");el.type="button";el.className=(primary?"primary":"choice")+(final?" final-choice":"");el.textContent=text;el.addEventListener("click",e=>{e.preventDefault();if(busy)return;musicStart();fn()});$("controls").append(el);return el}
function render(){cancel();const b=beat();if(state.chapter==="title"){$("art").innerHTML=sceneArt("future");$("actors").replaceChildren();$("props").replaceChildren();$("weather").className="weather";$("scene-label").classList.add("hidden");$("phone").classList.add("hidden");$("title-overlay").classList.remove("hidden");$("dialogue-panel").classList.add("hidden");$("chapter-tag").textContent="PROLOGUE · 2024 / 2048";$("scene-place").textContent="Between two moments";setMood();return}if(!b){notify("This saved scene could not be found. Start a new story or load another save.");return}$("title-overlay").classList.add("hidden");$("dialogue-panel").classList.remove("hidden");renderVisual(b);{const stg=$("stage");stg.dataset.fade=b.fade||"";stg.dataset.close=b.close?"1":"";stg.dataset.glitch=b.glitch?"1":""}marker(b.scene);if(b.memory&&!state.memories.includes(b.memory))state.memories.push(b.memory);if(b.connection)state.connection=b.connection;(b.phone||[]).forEach(([who,text],i)=>addMessage(`${id()}:script:${i}`,who,text));if(b.releaseSend)addMessage("ending:letter:release","Elara","whatever you choose, you don't have to choose it for me.");drawChat(!!b.phone||!!b.releaseSend||!!b.releaseRead);if(b.releaseSend)state.releaseSent=true;if(b.releaseRead){if(!state.releaseSent||!state.chat.some(m=>m.id==="ending:letter:release")){notify("The release message must arrive before Mira reads it.");return}state.releaseRead=true}if(b.independent){if(!state.releaseRead){notify("Mira must read Elara’s message before making this decision.");return}state.independent=true}history(id(),b.speaker,b.text);$("speaker").textContent=b.speaker==="Mira"?safeName(state.miraPresentation.displayName).toUpperCase()+" · 2024":({Elara:"ELARA · 2048",Adrian:"ADRIAN · 2024",Celeste:"CELESTE · 2024",Narrator:"NARRATION",Phone:"SYSTEM",Officiant:"OFFICIANT · 2024"})[b.speaker]||b.speaker.toUpperCase();$("story-line").textContent=b.text;$("chapter-tag").textContent=state.chapter==="consequence"?titles.five:state.chapter==="ending"?titles.ending:titles[state.chapter];$("scene-place").textContent=state.chapter==="five"&&state.index===0?"Wedding day · three days after the first message":locations[b.scene];$("beat-count").textContent=state.chapter==="consequence"?"THE CHOICE IN MOTION":progressText();$("controls").replaceChildren();if(state.pending?.source===id()){renderPending();return}if(b.decision){[["Proceed with the wedding.","expected"],["Stop the wedding and choose a life of her own.","own"],["Not today. Postpone, and rebuild the plan together.","different"],...(state.flags.last==="release"?[["Read Elara’s letter first, then decide alone.","letter"]]:[])].forEach(([text,k])=>button(text,()=>selectEnding(text,k),false,true))}else if(b.choices){if(b.prompt){const pr=document.createElement("p");pr.className="vu-prompt";pr.textContent=b.prompt;$("controls").append(pr)}b.choices.forEach((choice,i)=>button(choice.text,()=>choose(choice,i),false,state.chapter==="five"))}else if(b.ending){if(!state.endings.includes(state.endingKey))state.endings.push(state.endingKey);{const rc=document.createElement("div");rc.className="vu-recap";const h=document.createElement("h4");h.textContent="HOW YOU GOT HERE";rc.append(h);recapLines(state).forEach(t=>{const q=document.createElement("p");q.textContent=t;rc.append(q)});const sm=document.createElement("p");sm.className="vu-recap-s";sm.textContent=`Trust ${state.trust} · Belief ${state.acceptance} · Self ${state.self} · Honesty with Adrian ${state.honesty} · Elara’s respect ${state.respect} · Timeline ${state.stability}`;rc.append(sm);$("controls").append(rc)}button("REPLAY THE STORY",start,true);button("MAIN MENU",mainMenu)}else button("Continue →",advance,true);setMood()}
function move(chapter,index=0){if(chapter==="ending"&&(!endings[state.endingKey]||state.endingKey==="letter"&&!state.decisionKey))return false;if(chapter==="consequence"&&!consequences[state.endingKey])return false;if(chapters.includes(chapter)){const a=chapters.indexOf(state.chapter),b=chapters.indexOf(chapter);if(b<0||a<0||b>a+1||b<a||!story[chapter]?.[index])return false}state.chapter=chapter;state.index=index;busy=false;render();return true}
function advance(){if(busy||state.pending)return;const b=beat();if(!b||b.choices||b.decision||b.ending)return;sound(310);if(state.chapter==="consequence"){move("ending");return}if(state.chapter==="ending"){if(state.endingKey==="letter"&&state.index===3&&!state.independent)return;{const ni=nextIn(endingSequences[state.endingKey],state.index+1);if(ni>=0)move("ending",ni)}return}const seq=story[state.chapter];{const ni=nextIn(seq,state.index+1);if(ni>=0){move(state.chapter,ni);return}}const next=chapters[chapters.indexOf(state.chapter)+1];if(next){const f=nextIn(story[next],0);move(next,f<0?0:f)}}
function applyChoice(p){if(state.committed.includes(p.choiceId))return;const c=beat()?.choices?.[p.option];if(!c)return;for(const [name,value] of Object.entries(c.delta||{}))state[name]=Math.max(-8,Math.min(9,(state[name]||0)+value));Object.assign(state.flags,c.flags||{});for(const flag of ["truth","asked","afraid","released"])if(c.flags?.[flag])state[flag]=true;state.committed.push(p.choiceId);history(p.choiceId,"Choice",c.text)}
function choiceDelay(){return reduced()?80:state.settings.speed==="instant"?100:state.settings.speed==="slow"?900:500}
function choose(c,i){if(busy||state.pending||beat()?.choices?.[i]!==c)return;const choiceId=id()+":choice:"+i;if(state.committed.includes(choiceId))return;state.pending={source:id(),choiceId,option:i,stage:"selected"};applyChoice(state.pending);if(beat().phone){addMessage(choiceId+":sent","Elara",c.text);state.pending.stage="sent";sound(880)}else sound(440);render()}
function renderPending(){const p=state.pending,c=beat()?.choices?.[p.option];if(!c){state.pending=null;render();return}const host=$("controls");host.replaceChildren();const selected=document.createElement("p");selected.className="choice";selected.textContent=c.text;selected.dataset.vu=JSON.stringify({as:c.as||"",live:!!c.live,ghost:!!c.ghost,send:c.send||[],say:c.say||[],re:c.re||[],delta:c.delta||{}});host.append(selected);drawChat(!!beat().phone);const go=button("Continue →",finishPending,true);if(beat().phone&&c.reply&&p.stage==="sent"){go.disabled=true;const t=document.createElement("div");t.className="typing";t.textContent="●  ●  ●";$("chat").append(t);later(()=>{if(state.pending?.choiceId!==p.choiceId)return;addMessage(p.choiceId+":reply","Mira",c.reply);state.pending.stage="replied";$("chat").querySelector(".typing")?.remove();drawChat(true);sound(470);go.disabled=false},choiceDelay())}}
function finishPending(){const p=state.pending;if(!p||p.source!==id())return;const c=beat()?.choices?.[p.option];if(!c)return;if(beat().phone&&c.reply&&!state.chat.some(m=>m.id===p.choiceId+":reply")){addMessage(p.choiceId+":reply","Mira",c.reply);drawChat(true)}state.pending=null;{const ni=nextIn(state.chapter==="ending"?endingSequences[state.endingKey]:story[state.chapter],state.index+1);if(state.chapter==="ending"){if(ni>=0)move("ending",ni);return}if(ni>=0)move(state.chapter,ni);else{const next=chapters[chapters.indexOf(state.chapter)+1],f=next?nextIn(story[next],0):0;move(next,f<0?0:f)}}}
function selectEnding(text,k){if(k==="letter"&&state.flags.last!=="release")return;if(busy||state.chapter!=="five"||!beat()?.decision||state.pending||!endings[k])return;const event="five:5:decision";if(state.committed.includes(event))return;state.committed.push(event);history(event,"Mira’s decision",text);sound(523);state.decisionKey=k;state.endingKey=k;if(k==="letter"){state.releaseSent=false;state.releaseRead=false;state.independent=false;move("ending",0)}else move("consequence",0)}
